import {STORAGE,COURSES,WORDS,text,validate} from './curriculum-model.js';
import {lessonFor,learningStatus,frameEvidence} from './lesson-content.js';
const lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ko',en=lang==='en',t=p=>text(p,lang),say=(ko,eng)=>en?eng:ko,w=k=>t(WORDS[k]||k),$=id=>document.getElementById(id),el=(tag,parent,value)=>{const o=document.createElement(tag);if(value!==undefined)o.textContent=value;parent.append(o);return o;};let data;document.documentElement.lang=lang;
for(const [id,label,href]of [['lab',say('실험실','Laboratory'),'index.html'],['guide',say('지도서 대조·교사 안내','Guide and source coverage'),'guide.html'],['legacy',say('이전 중등 기록','Earlier middle-school records'),'teacher-legacy.html']]){$(id).textContent=label;$(id).href=href+'?lang='+lang;}
$('title').textContent=say('과정별 실험·학습 근거','Experiment and learning evidence');$('intro').textContent=say('조건을 눌렀다는 사실과 실제 관찰·설명·적용 근거를 구분해 검토합니다. 발표와 협력은 교사가 확인합니다.','Distinguish button presses from observation, explanation and transfer evidence. Teachers review presentation and collaboration.');$('reload').textContent=say('이 기기 기록 불러오기','Load this device’s records');$('import-label').textContent=say('JSON 파일 불러오기 ','Import JSON ');$('import').setAttribute('aria-label',say('학생 기록 JSON','Student record JSON'));$('export').textContent=w('export');$('print').textContent=say('인쇄','Print');$('scope').textContent=say('자동 점수·등급·학습 인증을 만들지 않습니다. 안내 조건의 실제 측정, 첫 답과 수정 답, 자기 설명, 조사 출처, 설계 수정, 동료 의견을 검토하세요. 이전 버전 실험은 보존하되 새 과정 완료와 구분합니다. 파일을 불러와도 이 기기의 원래 기록을 덮어쓰지 않습니다.','No automatic score, grade or mastery certification. Review guided measurements, original and revised answers, explanations, sources, design revisions and feedback. Preserve earlier experiments separately from new completion. Imported files do not overwrite this device’s records.');
const metric=m=>w(m.key)+': '+(m.value===null?'—':Math.abs(m.value)<1e-8?'0':Number.isInteger(m.value)?m.value:m.value.toFixed(Math.abs(m.value)<.1?3:2))+(m.unit?' '+(m.unit==='relative'?say('칸','units'):m.unit):'');
function render(){const root=$('records');root.replaceChildren();for(const [cid,c]of Object.entries(COURSES)){el('h2',root,t(c.label));for(const a of c.activities){const e=data.courses[cid].experiments[a.id],l=lessonFor(cid,a.id),s=learningStatus(l,e),d=el('details',root);el('summary',d,t(a.title)+' · '+e.trials.length+say('회',' trials')+' · '+(s.complete?say('실험·설명 확인','Evidence checked'):say('진행 중/미실시','In progress/not attempted')));el('small',d,a.codes.join(', ')+' · '+say('지도서 쪽 ','Source pages ')+l.pages);el('p',d,say('안내 측정 ','Guided measurements ')+s.measured+'/'+s.required+' · '+say('확인 질문 ','Check questions ')+s.checked+'/'+s.questions+(l.peer?say(' · 발표·협력은 교사 확인',' · presentation/collaboration need teacher review'):''));const list=el('ul',d);frameEvidence(l,e).forEach((done,i)=>el('li',list,(done?'✓ ':'○ ')+t(l.frames[i].title)));for(const [key,label]of [['plan',say('계획·조사·출처','Plan, investigation and sources')],['reflection',say('예상과 비교','Prediction review')],['peer',say('발표·동료 의견','Presentation/feedback')]]){if(e.learning[key]){el('h3',d,label);el('p',d,e.learning[key]).className='notes';}}el('h3',d,say('학생 설명','Student explanation'));el('p',d,e.note||say('미작성','Not written')).className='notes';for(const [id,value]of Object.entries(e.learning.predictions))el('p',d,say('처음 예상 ','Initial prediction ')+id+': '+value);for(const x of l.extensions||[])el('p',d,t(x.title)+': '+(e.learning.extensions?.[x.id]||say('미실시/미작성','Not submitted')));if(!e.trials.length){el('p',d,say('측정 미실시','No measurements'));continue;}
 const scroll=el('div',d);scroll.className='scroll';const table=el('table',scroll),head=el('tr',el('thead',table));for(const title of [say('회·안내 행','Trial/frame'),w('condition'),w('observation')])el('th',head,title);const body=el('tbody',table);for(const trial of e.trials){const row=el('tr',body);el('td',row,trial.id+' · '+(trial.legacy?say('이전 기록','Earlier'):trial.frameId||say('자유','Free')));el('td',row,a.controls.map(c=>w(c.label)+': '+(c.options?w(c.options.find(([v])=>v===trial.inputs[c.key])?.[1]):trial.inputs[c.key]+' '+c.unit)).join(' · '));const out=el('td',row,trial.result.metrics.map(metric).join(' · '));if(trial.studentReading!==undefined)el('small',out,say('학생이 읽은 값 ','Student reading ')+trial.studentReading+' g · '+(trial.readAttempts?.length||1)+say('번 시도',' attempts'));el('small',out,say('영점 ','Zero ')+trial.zeroed+' · '+say('물체 ','Loaded ')+trial.placed+' · '+say('봉투 ','Bag ')+!!trial.bag);}
 const attempts=el('details',d);el('summary',attempts,say('첫 답과 수정 답 기록','Original and revised answers'));for(const attempt of e.learning.attempts){const q=[...l.questions,l.transfer].find(q=>q.id===attempt.id);el('p',attempts,attempt.at+' · '+(q?t(q.title):attempt.id)+' → '+(q?t(q.options[attempt.value]):attempt.value));}}}$('export').disabled=false;}
function accept(value){data=validate(value);render();$('status').textContent=say('기록을 검증하고 측정값을 다시 계산했습니다.','Records validated; measurements recomputed.');}
function load(){try{const raw=localStorage.getItem(STORAGE);if(!raw)throw Error();accept(JSON.parse(raw));}catch{$('status').textContent=say('기록이 없거나 현재 형식으로 읽을 수 없습니다. 저장한 JSON을 선택하세요.','No readable records. Select a saved JSON file.');}}
$('reload').onclick=load;$('import').onchange=async()=>{try{const file=$('import').files[0];if(!file)return;if(file.size>8_000_000)throw Error();accept(JSON.parse(await file.text()));}catch{$('status').textContent=say('지원하지 않는 기록 형식입니다. 원래 파일은 변경하지 않았습니다.','Unsupported record format. Original file is unchanged.');}};$('export').onclick=()=>{if(!data)return;const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='force-lab-courses-reviewed.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};let printState=[];window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('#records details')].map(d=>[d,d.open]);for(const[d]of printState)d.open=true;});window.addEventListener('afterprint',()=>{for(const[d,open]of printState)d.open=open;printState=[];});$('print').onclick=()=>window.print();load();
